import { neonColors } from "../constants/color";
import { Card } from "../types";
import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

export default function CardItem({ id, card }: { id: number, card: Card }) {
    const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
  } = useSortable({ id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    background: "#fff",
    padding: 8,
    marginBottom: 8,
  };
  const randomColor = neonColors[Math.floor(Math.random() * neonColors.length)];
  return (
    <div ref={setNodeRef} {...attributes} {...listeners} style={{ borderWidth: 2,color:randomColor,borderStyle: "solid", borderColor: randomColor, padding: 8, marginBottom: 8, borderRadius: 10 }}>
      {card.title}
      {card.description && <p style={{ marginTop: 4, marginBottom: 0, fontSize: 14, fontFamily: "Arial, sans-serif" }}>{card.description}</p>}
    </div>
  );
}
